services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Xactimate estimating","Fallen tree claims","Hurricane deductibles","Ice dam claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}]},{"@type":"WebSite","@id":"https://connecticutinsuranceappraiser.com/#website","url":"https://connecticutinsuranceappraiser.com/","name":"Connecticut Insurance Appraiser","publisher":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/#webpage","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/","name":"How Insurance Appraisal Works in Connecticut | 8 Steps","description":"Connecticut insurance appraisal process in eight steps: the written demand, naming appraisers, the umpire, negotiation and the signed award.","inLanguage":"en-US","isPartOf":{"@id":"https://connecticutinsuranceappraiser.com/#website"},"about":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"publisher":{"@id":"https://connecticutinsuranceappraiser.com/#business"},"dateModified":"2026-11-16","primaryImageOfPage":{"@type":"ImageObject","url":"https://connecticutinsuranceappraiser.com/assets/img/photos/team-laptops.webp","width":960,"height":640},"breadcrumb":{"@id":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/#breadcrumb"},"mainEntity":{"@id":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/#howto"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://connecticutinsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Appraisal process","item":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"}],"@id":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/#breadcrumb"},{"@type":"HowTo","name":"How insurance appraisal works in Connecticut","description":"The eight stages of a property insurance appraisal under a Connecticut policy.","totalTime":"P10W","step":[{"@type":"HowToStep","position":1,"name":"Pin down the disagreement","text":"Confirm coverage is accepted and that the dispute is about the amount of loss: scope, price, matching or the value of contents.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":2,"name":"Read the appraisal condition","text":"Find the appraisal paragraph in your policy and note who may demand it, how, and how many days each side has to name an appraiser.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":3,"name":"Send the written demand","text":"Demand appraisal in writing, identify the claim and the disputed amount, and keep proof of delivery.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":4,"name":"Name the appraisers","text":"Each side names a competent and disinterested appraiser within the policy’s window and tells the other side who it is.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":5,"name":"Select the umpire","text":"The two appraisers agree on a neutral umpire. If they can’t, either side can usually ask a court to appoint one.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":6,"name":"Inspect, compare and negotiate","text":"The appraisers inspect, exchange estimates and resolve as many line items as they can between themselves.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":7,"name":"Submit open items to the umpire","text":"Anything still in dispute goes to the umpire with photos, measurements and pricing support from both appraisers.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"},{"@type":"HowToStep","position":8,"name":"Sign the award and get paid","text":"An award signed by any two of the three sets the amount of loss. The carrier then pays under the policy’s terms.","url":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/"}],"@id":"https://connecticutinsuranceappraiser.com/ct-appraisal-process/#howto"}]}</script>
